def complexity(card):
    """DR-2026-11-20-07 §7: 1 + required capabilities with no registered Foundry Engine
    + 1 if any capability is out of scope by law; capped at 5."""
    gaps = sum(1 for c in card.get("required_capabilities", []) if not c.get("covered_by"))
    law = any(c.get("out_of_scope_by_law") for c in card.get("required_capabilities", []) + card.get("optional_capabilities", []))
    return min(5, 1 + gaps + (1 if law else 0))
